const prefersReducedMotion = window.matchMedia("(prefers-reduced-motion: reduce)").matches;

function createPetals() {
  const layer = $("#petals");
  const count = window.innerWidth < 600 ? 12 : 22;
  for (let index = 0; index < count; index += 1) {
    const petal = document.createElement("span");
    const drift = (index % 2 ? 1 : -1) * (18 + (index * 19) % 70);
    petal.className = "petal";
    petal.style.setProperty("--left", `${(index * 67 + 5) % 100}%`);
    petal.style.setProperty("--drift", `${drift}px`);
    petal.style.setProperty("--end-drift", `${drift * -0.55}px`);
    petal.style.setProperty("--duration", `${9 + (index * 7) % 11}s`);
    petal.style.setProperty("--delay", `${-((index * 3) % 18)}s`);
    layer.append(petal);
  }
}

function createStarfield() {
  const canvas = $("#sky");
  const context = canvas.getContext("2d");
  const stars = [];
  let width = 0;
  let height = 0;
  let animationFrame = 0;
  let pointerX = 0;
  let pointerY = 0;

  const resize = () => {
    const ratio = Math.min(window.devicePixelRatio || 1, 1.5);
    width = window.innerWidth;
    height = window.innerHeight;
    canvas.width = Math.round(width * ratio);
    canvas.height = Math.round(height * ratio);
    context.setTransform(ratio, 0, 0, ratio, 0, 0);
    stars.length = 0;
    const count = Math.min(150, Math.round((width * height) / 6500));
    for (let index = 0; index < count; index += 1) {
      stars.push({
        x: Math.random() * width,
        y: Math.random() * height,
        radius: Math.random() * 1.3 + 0.3,
        phase: Math.random() * Math.PI * 2,
        speed: Math.random() * 0.018 + 0.004,
      });
    }
  };

  const onPointerMove = (event) => {
    pointerX = event.clientX / Math.max(width, 1) - 0.5;
    pointerY = event.clientY / Math.max(height, 1) - 0.5;
  };

  const draw = () => {
    context.clearRect(0, 0, width, height);
    const time = performance.now() * 0.001;
    for (const star of stars) {
      const glow = 0.24 + (Math.sin(time * star.speed * 45 + star.phase) + 1) * 0.28;
      const x = star.x + pointerX * star.radius * 5;
      const y = star.y + pointerY * star.radius * 5;
      context.beginPath();
      context.arc(x, y, star.radius, 0, Math.PI * 2);
      context.fillStyle = `rgba(255, 218, 227, ${glow})`;
      context.shadowBlur = star.radius > 1 ? 9 : 0;
      context.shadowColor = "#f8aabd";
      context.fill();
    }
    context.shadowBlur = 0;
    if (!prefersReducedMotion) animationFrame = requestAnimationFrame(draw);
  };

  resize();
  draw();
  window.addEventListener("resize", resize);
  window.addEventListener("pointermove", onPointerMove, { passive: true });
  return () => {
    cancelAnimationFrame(animationFrame);
    window.removeEventListener("resize", resize);
    window.removeEventListener("pointermove", onPointerMove);
  };
}

function heartPath(context, size) {
  context.beginPath();
  context.moveTo(0, size * 0.3);
  context.bezierCurveTo(-size, -size * 0.35, -size * 0.8, -size, 0, -size * 0.43);
  context.bezierCurveTo(size * 0.8, -size, size, -size * 0.35, 0, size * 0.3);
  context.closePath();
}

let bursts = [];
let fireworkFrame = 0;
let fireworkUntil = 0;
let fireworkEndTimeout = 0;
let lastFireworkTime = 0;

function resizeFireworks() {
  const ratio = Math.min(window.devicePixelRatio || 1, 1.5);
  fireworksCanvas.width = Math.round(window.innerWidth * ratio);
  fireworksCanvas.height = Math.round(window.innerHeight * ratio);
  fireworksCanvas.style.width = `${window.innerWidth}px`;
  fireworksCanvas.style.height = `${window.innerHeight}px`;
  fireworksContext.setTransform(ratio, 0, 0, ratio, 0, 0);
}

function launchBurst(x, y, color, shape = "spark") {
  const count = shape === "heart" ? 11 : 34;
  for (let index = 0; index < count; index += 1) {
    const angle = shape === "heart" ? (index / count) * Math.PI * 2 : Math.random() * Math.PI * 2;
    const speed = shape === "heart" ? 1.2 + Math.random() * 1.1 : 1 + Math.random() * 3.2;
    bursts.push({
      x,
      y,
      vx: Math.cos(angle) * speed,
      vy: Math.sin(angle) * speed - (shape === "heart" ? 0 : 1.3),
      size: shape === "heart" ? 5 + Math.random() * 3 : 1.4 + Math.random() * 2,
      color,
      shape,
      life: 0.85 + Math.random() * 0.8,
      age: 0,
    });
  }
}

function drawFireworks(timestamp) {
  const width = window.innerWidth;
  const height = window.innerHeight;
  const delta = Math.min((timestamp - (lastFireworkTime || timestamp)) / 1000, 0.04);
  lastFireworkTime = timestamp;
  fireworksContext.clearRect(0, 0, width, height);

  bursts = bursts.filter((particle) => particle.age < particle.life);
  for (const particle of bursts) {
    particle.age += delta;
    particle.x += particle.vx * 55 * delta;
    particle.y += particle.vy * 55 * delta;
    particle.vy += 1.15 * delta;
    const fade = Math.max(0, 1 - particle.age / particle.life);
    fireworksContext.save();
    fireworksContext.globalAlpha = fade;
    fireworksContext.translate(particle.x, particle.y);
    if (particle.shape === "heart") {
      fireworksContext.scale(particle.size / 8, particle.size / 8);
      heartPath(fireworksContext, 8);
      fireworksContext.fillStyle = particle.color;
      fireworksContext.shadowBlur = 13;
      fireworksContext.shadowColor = particle.color;
      fireworksContext.fill();
    } else {
      fireworksContext.beginPath();
      fireworksContext.arc(0, 0, particle.size * fade, 0, Math.PI * 2);
      fireworksContext.fillStyle = particle.color;
      fireworksContext.shadowBlur = 11;
      fireworksContext.shadowColor = particle.color;
      fireworksContext.fill();
    }
    fireworksContext.restore();
  }

  if (timestamp < fireworkUntil || bursts.length) {
    fireworkFrame = requestAnimationFrame(drawFireworks);
  } else {
    fireworksContext.clearRect(0, 0, width, height);
    fireworkFrame = 0;
    lastFireworkTime = 0;
  }
}

function celebrate() {
  resizeFireworks();
  const palette = ["#ff7996", "#ffd4a1", "#f7aec0", "#fff0d6", "#d9a1f2"];
  const width = window.innerWidth;
  const height = window.innerHeight;
  const totalBursts = prefersReducedMotion ? 1 : 7;
  window.clearTimeout(fireworkEndTimeout);
  fireworkUntil = performance.now() + (prefersReducedMotion ? 1200 : 4500);
  for (let index = 0; index < totalBursts; index += 1) {
    const x = width * (0.13 + Math.random() * 0.74);
    const y = height * (0.17 + Math.random() * 0.55);
    window.setTimeout(() => {
      launchBurst(x, y, palette[index % palette.length]);
      launchBurst(x, y, "#ff9eb2", "heart");
      if (!fireworkFrame) fireworkFrame = requestAnimationFrame(drawFireworks);
    }, index * 190);
  }
  fireworkEndTimeout = window.setTimeout(() => {
    fireworkUntil = 0;
  }, prefersReducedMotion ? 1200 : 4500);
}

function openExperience() {
  intro.classList.add("leaving");
  intro.setAttribute("aria-hidden", "true");
  window.setTimeout(() => {
    intro.hidden = true;
    experience.hidden = false;
    experience.classList.add("shown");
    window.scrollTo({ top: 0, behavior: prefersReducedMotion ? "instant" : "smooth" });
    $("#top").setAttribute("tabindex", "-1");
    $("#top").focus({ preventScroll: true });
  }, prefersReducedMotion ? 0 : 650);
}

function setEnvelopeOpen(open) {
  const envelope = $("#envelope");
  envelope.classList.toggle("is-open", open);
  envelope.setAttribute("aria-expanded", String(open));
  $("#envelopeHint").textContent = open ? "كلمة خارجة من قلبي" : "كليكي على القلب باش تحلّي الرسالة";
  $("#letterCard").hidden = !open;
  $("#continueButton").hidden = !open;
}

function setupReasons() {
  document.querySelectorAll(".reason-card").forEach((card) => {
    card.addEventListener("click", () => {
      const isOpen = card.classList.toggle("is-flipped");
      const front = card.querySelector(".reason-front");
      const back = card.querySelector(".reason-back");
      if (isOpen) {
        back.innerHTML = `<span>${card.dataset.message}</span><small>ديما معاك ♥</small>`;
        front.hidden = true;
        back.hidden = false;
        card.setAttribute("aria-label", `${card.dataset.title}، رجّعي العنوان`);
      } else {
        front.hidden = false;
        back.hidden = true;
        card.setAttribute("aria-label", `${card.dataset.title}، قراي هاد الكلمة الزوينة`);
      }
    });
  });
}

function setupCounter() {
  const grid = $("#counterGrid");
  const start = new Date(relationshipStartDate);
  if (!relationshipStartDate || Number.isNaN(start.getTime()) || start > new Date()) {
    if (relationshipStartDate) {
      grid.innerHTML = '<div class="counter-empty"><span>♥</span><p>راجعي التاريخ اللي دخلتي فـ script.js.</p><small>خاص التاريخ يكون صحيح وما يكونش فالقدّام.</small></div>';
    }
    return;
  }

  grid.replaceChildren();
  const units = [
    { label: "نهار", seconds: 86400 },
    { label: "ساعة", seconds: 3600 },
    { label: "دقيقة", seconds: 60 },
    { label: "ثانية", seconds: 1 },
  ];
  const cells = units.map(({ label }) => {
    const cell = document.createElement("div");
    cell.className = "counter-cell";
    const value = document.createElement("span");
    const caption = document.createElement("small");
    caption.textContent = label;
    cell.append(value, caption);
    grid.append(cell);
    return value;
  });

  const update = () => {
    const elapsed = Math.max(0, Math.floor((Date.now() - start.getTime()) / 1000));
    let remaining = elapsed;
    const values = units.map(({ seconds }, index) => {
      const value = index === 0 ? Math.floor(remaining / seconds) : Math.floor(remaining / seconds) % (index === 1 ? 24 : 60);
      if (index > 0) remaining %= seconds;
      return value;
    });
    cells.forEach((cell, index) => {
      cell.textContent = index === 0
        ? new Intl.NumberFormat("ar-MA").format(values[index])
        : new Intl.NumberFormat("ar-MA", { minimumIntegerDigits: 2, useGrouping: false }).format(values[index]);
    });
  };
  update();
  window.setInterval(update, 1000);
}

const photoStoreKey = "11-11-rachida-memories";
const bundledMemory = { src: 'data:image/jpeg;base64,', caption: 'واحد الذكرى زوينة ديالنا ❤️' };
let photos = [];
let currentPhoto = 0;

function loadPhotos() {
  try {
    const saved = localStorage.getItem(photoStoreKey);
    photos = saved ? JSON.parse(saved) : [bundledMemory];
    if (!Array.isArray(photos)) throw new Error("صيغة الصور المحفوظة ماشي صحيحة.");
  } catch (error) {
    console.error("ما قدرناش نقراو الصور اللي تحفظو.", error);
    photos = [bundledMemory];
    showGalleryError("ما قدرناش نفتحو الذكريات المحفوظة. اختاري الصور من جديد.");
  }
}

function showGalleryError(message) {
  const error = $("#galleryError");
  error.textContent = message;
  error.hidden = false;
}

function savePhotos() {
  try {
    localStorage.setItem(photoStoreKey, JSON.stringify(photos));
    $("#galleryError").hidden = true;
    $("#galleryNote").hidden = photos.length === 0;
  } catch (error) {
    console.error("ما قدرناش نحفظو الصور فالمتصفح.", error);
    showGalleryError("المساحة ديال هاد المتصفح عامرة. حيدي شي صورة ولا اختاري تصاور أصغر.");
    return false;
  }
  return true;
}

function renderGallery() {
  const empty = $("#galleryEmpty");
  const frame = $("#photoFrame");
  const controls = $("#galleryControls");
  const note = $("#galleryNote");
  empty.hidden = photos.length > 0;
  frame.hidden = photos.length === 0;
  controls.hidden = photos.length < 2;
  note.hidden = photos.length === 0;
  if (!photos.length) return;

  currentPhoto = (currentPhoto + photos.length) % photos.length;
  const photo = photos[currentPhoto];
  $("#photoImage").src = photo.src;
  $("#photoImage").alt = photo.caption || "ذكرى زوينة ديالنا";
  $("#photoCaption").value = photo.caption || "";
  $("#photoCount").textContent = `${new Intl.NumberFormat("ar-MA", { minimumIntegerDigits: 2, useGrouping: false }).format(currentPhoto + 1)} / ${new Intl.NumberFormat("ar-MA", { minimumIntegerDigits: 2, useGrouping: false }).format(photos.length)}`;
}

function imageToDataUrl(file) {
  return new Promise((resolve, reject) => {
    const objectUrl = URL.createObjectURL(file);
    const image = new Image();
    image.onload = () => {
      const scale = Math.min(1, 1400 / Math.max(image.naturalWidth, image.naturalHeight));
      const canvas = document.createElement("canvas");
      canvas.width = Math.max(1, Math.round(image.naturalWidth * scale));
      canvas.height = Math.max(1, Math.round(image.naturalHeight * scale));
      const context = canvas.getContext("2d");
      URL.revokeObjectURL(objectUrl);
      if (!context) {
        reject(new Error("المتصفح ما قدرش يجهّز هاد الصورة."));
        return;
      }
      context.drawImage(image, 0, 0, canvas.width, canvas.height);
      try {
        resolve(canvas.toDataURL("image/jpeg", 0.82));
      } catch (error) {
        reject(error);
      }
    };
    image.onerror = () => {
      URL.revokeObjectURL(objectUrl);
      reject(new Error(`ما قدرناش نقراو الصورة ${file.name}.`));
    };
    image.src = objectUrl;
  });
}

async function addPhotos(files) {
  $("#galleryError").hidden = true;
  const images = Array.from(files).filter((file) => file.type.startsWith("image/"));
  if (images.length !== files.length) showGalleryError("عافاك اختاري غير تصاور.");
  let firstNewPhoto = -1;
  for (const file of images) {
    try {
      const src = await imageToDataUrl(file);
      if (firstNewPhoto < 0) firstNewPhoto = photos.length;
      photos.push({ src, caption: "" });
    } catch (error) {
      console.error("ما قدرناش نزيدو هاد الصورة للذكريات.", error);
      showGalleryError(error.message || "ما قدرناش نزيدو هاد الصورة. جرّبي صورة أخرى.");
    }
  }
  if (firstNewPhoto >= 0) {
    currentPhoto = firstNewPhoto;
    if (savePhotos()) renderGallery();
  }
}

function setupGallery() {
  loadPhotos();
  renderGallery();
  $("#photoUpload").addEventListener("change", async (event) => {
    await addPhotos(event.target.files || []);
    event.target.value = "";
  });
  $("#photoCaption").addEventListener("input", (event) => {
    if (!photos[currentPhoto]) return;
    photos[currentPhoto].caption = event.target.value;
    $("#photoImage").alt = event.target.value || "ذكرى زوينة ديالنا";
    savePhotos();
  });
  $("#previousPhoto").addEventListener("click", () => {
    currentPhoto = (currentPhoto - 1 + photos.length) % photos.length;
    renderGallery();
  });
  $("#nextPhoto").addEventListener("click", () => {
    currentPhoto = (currentPhoto + 1) % photos.length;
    renderGallery();
  });
  $("#removePhoto").addEventListener("click", () => {
    photos.splice(currentPhoto, 1);
    currentPhoto = Math.max(0, currentPhoto - 1);
    if (savePhotos()) renderGallery();
  });
}

function setupMusic() {
  const audio = $("#musicAudio");
  const toggle = $("#musicToggle");
  const volumeControl = $("#musicVolume");
  const title = $("#musicTitle");
  const state = $("#musicState");
  let context = null;
  let timer = 0;
  let noteIndex = 0;
  const melody = [261.63, 329.63, 392, 329.63, 293.66, 349.23, 440, 392, 261.63, 329.63, 392, 523.25, 440, 392, 329.63, 293.66];
  let playing = false;

  if (musicSource.trim()) audio.src = musicSource.trim();

  const playNote = (frequency, start, duration, level) => {
    const master = context.createGain();
    const volume = Number(volumeControl.value);
    master.gain.setValueAtTime(0.0001, start);
    master.gain.exponentialRampToValueAtTime(Math.max(volume * level, 0.0002), start + 0.025);
    master.gain.exponentialRampToValueAtTime(0.0001, start + duration);
    master.connect(context.destination);
    [1, 2.01, 3.9].forEach((partial, index) => {
      const oscillator = context.createOscillator();
      const overtone = context.createGain();
      oscillator.type = "sine";
      oscillator.frequency.value = frequency * partial;
      overtone.gain.value = index === 0 ? 1 : index === 1 ? 0.19 : 0.055;
      oscillator.connect(overtone);
      overtone.connect(master);
      oscillator.start(start);
      oscillator.stop(start + duration + 0.03);
    });
  };

  const stop = async () => {
    playing = false;
    audio.pause();
    window.clearInterval(timer);
    if (context && context.state === "running") await context.suspend();
    toggle.classList.remove("playing");
    toggle.querySelector(".play-icon").textContent = "▶";
    toggle.setAttribute("aria-label", "شغّلي الموسيقى");
    title.textContent = "نغمة هادئة كتسناك";
    state.textContent = "ضغطي باش تبدا";
  };

  const start = async () => {
    if (musicSource.trim()) {
      audio.volume = Number(volumeControl.value);
      try {
        await audio.play();
      } catch (error) {
        console.error("ما قدرناش نشغلو ملف الموسيقى اللي موجد.", error);
        state.textContent = "ما خدامش ملف الموسيقى";
        return;
      }
    } else {
      const AudioContext = window.AudioContext || window.webkitAudioContext;
      if (!AudioContext) {
        state.textContent = "هاد المتصفح ما كيدعمش الموسيقى";
        return;
      }
      try {
        if (!context) context = new AudioContext();
        await context.resume();
      } catch (error) {
        console.error("ما قدرناش نبداو النغمة الهادئة.", error);
        state.textContent = "ما قدرناش نشغلو الموسيقى";
        return;
      }
      timer = window.setInterval(() => {
        const index = noteIndex % melody.length;
        const now = context.currentTime;
        playNote(melody[index], now, 1.35, 0.11);
        if (index % 4 === 0) playNote(melody[index] / 2, now, 2, 0.045);
        noteIndex += 1;
      }, 560);
    }
    playing = true;
    toggle.classList.add("playing");
    toggle.querySelector(".play-icon").textContent = "Ⅱ";
    toggle.setAttribute("aria-label", "حبسي الموسيقى");
    title.textContent = "نغمة هادئة ليك";
    state.textContent = "كتعزف دابا";
  };

  toggle.addEventListener("click", () => {
    if (playing) void stop();
    else void start();
  });
  $("#musicHint").addEventListener("click", () => {
    if (!playing) void start();
    toggle.focus();
  });
  volumeControl.addEventListener("input", () => {
    audio.volume = Number(volumeControl.value);
  });
  audio.addEventListener("error", () => {
    if (musicSource.trim()) {
      console.error("ما قدرناش نحمّلو ملف الموسيقى اللي موجد فـ script.js.");
      state.textContent = "راجعي رابط الموسيقى";
    }
  });
  window.addEventListener("pagehide", () => {
    audio.pause();
    window.clearInterval(timer);
    if (context && context.state !== "closed") void context.close();
  });
}

function setupSurprise() {
  const revealButton = $("#revealSurprise");
  revealButton.addEventListener("click", () => {
    revealButton.hidden = true;
    $("#finalMessage").hidden = false;
    celebrate();
  });
}

function setupNavigation() {
  $("#enterExperience").addEventListener("click", () => {
    launchBurst(window.innerWidth / 2, window.innerHeight / 2, "#ff93aa", "heart");
    fireworkUntil = performance.now() + 1000;
    if (!fireworkFrame) fireworkFrame = requestAnimationFrame(drawFireworks);
    openExperience();
  });
  $("#envelope").addEventListener("click", () => {
    const isOpen = $("#envelope").getAttribute("aria-expanded") !== "true";
    setEnvelopeOpen(isOpen);
  });
  $("#continueButton").addEventListener("click", () => {
    $("#reasons").scrollIntoView({ behavior: prefersReducedMotion ? "instant" : "smooth" });
  });
  $("#backToTop").addEventListener("click", (event) => {
    event.preventDefault();
    window.scrollTo({ top: 0, behavior: prefersReducedMotion ? "instant" : "smooth" });
  });
  $("#backToStart").addEventListener("click", () => {
    experience.hidden = true;
    intro.hidden = false;
    intro.classList.remove("leaving");
    intro.removeAttribute("aria-hidden");
    window.scrollTo({ top: 0, behavior: "instant" });
    $("#enterExperience").focus({ preventScroll: true });
  });
}

createPetals();
createStarfield();
resizeFireworks();
window.addEventListener("resize", resizeFireworks);
setupCounter();
setupReasons();
setupGallery();
setupMusic();
setupSurprise();
setupNavigation();
